def mpfb_module(absolute_package_str):
    """The loaded MPFB module whose name ends with the given string (see dynamic_import in tests/__init__.py)."""
    for name, module in list(sys.modules.items()):
        if name.endswith(absolute_package_str):
            return module
    raise ValueError(f"No module found with name ending in {absolute_package_str}")


