FUR_PROPERTIES = hairproperties.FUR_PROPERTIES

# The assets the tests are run with. They have to be in the current asset pack, otherwise the test is skipped.
HAIR_ASSET = "basic_short_hair"
SECOND_HAIR_ASSET = "hedgehog"
FUR_ASSET = "fur_arms"

# Every kind of datablock the hair editor creates or touches
_TRACKED_DATA = ("objects", "meshes", "hair_curves", "curves", "materials", "images", "node_groups",
                 "lights", "armatures", "worlds")


# ---------------------------------------------------------------------------
# Asset pack
# ---------------------------------------------------------------------------

_PACK_CONTENTS = {}


def pack_objects(fur=False):
    """Names of the objects in the hair (or fur) asset blend, an empty set if it is not installed."""
    key = "fur" if fur else "hair"
    if key not in _PACK_CONTENTS:
        path = HairEditorService.get_fur_blend_path() if fur else HairEditorService.get_hair_blend_path()
        names = set()
        if path:
            with bpy.data.libraries.load(path, link=False) as (data_from, _data_to):
                names = set(data_from.objects)
        _PACK_CONTENTS[key] = names
    return _PACK_CONTENTS[key]


def require_pack_asset(asset_name, fur=False):
    """Skip the calling test unless the asset can be loaded from the installed asset pack."""
    installed = HairEditorService.is_fur_asset_installed() if fur else HairEditorService.is_hair_asset_installed()
    if not installed:
        pytest.skip("The hair editor asset pack is not installed")
    if asset_name not in pack_objects(fur):
        pytest.skip(f"'{asset_name}' is not in the installed asset pack")


# ---------------------------------------------------------------------------
# Keeping the file clean between tests
# ---------------------------------------------------------------------------

class DataSnapshot:
    """Notes down every datablock before a test and removes whatever the test added.

    SceneSnapshot only cleans up objects. The hair editor also leaves meshes, node groups, materials and images
    behind when a test fails half way, and those would then rename the datablocks of the next test (".001").
    """

    def __init__(self):
        self._before = {}

    def take(self):
        self._before = {kind: {block.as_pointer() for block in getattr(bpy.data, kind)} for kind in _TRACKED_DATA}

    def added(self, kind):
        return [block for block in getattr(bpy.data, kind) if block.as_pointer() not in self._before[kind]]

    def cleanup(self):
        if bpy.context.object is not None and bpy.context.object.mode != 'OBJECT':
            bpy.ops.object.mode_set(mode='OBJECT')
        # Objects first, they are what keeps the rest in use
        for kind in _TRACKED_DATA:
            for block in self.added(kind):
                try:
                    block.use_fake_user = False
                    getattr(bpy.data, kind).remove(block, do_unlink=True)
                except Exception as e:
                    print(f"DataSnapshot: could not remove {kind} {block}: {e}")


@pytest.fixture
def scratch():
    """Anything the test adds to the file is removed again afterwards."""
    snapshot = DataSnapshot()
    snapshot.take()
    yield snapshot
    snapshot.cleanup()


def datablock_counts():
    """How much of everything the file holds, for spotting leftovers."""
    return {kind: len(getattr(bpy.data, kind)) for kind in _TRACKED_DATA}


def leaked_since(before):
    """What grew since ``before`` was taken with datablock_counts()."""
    after = datablock_counts()
    return {kind: after[kind] - before[kind] for kind in before if after[kind] > before[kind]}


