def select(obj):
    """Make obj the only selected and the active object, which is what the operators work from."""
    ObjectService.deselect_and_deactivate_all()
    ObjectService.activate_blender_object(obj)


@pytest.fixture
def character(scratch):
    """A fresh basemesh, without a rig."""
    with HumanFixture() as fixture:
        yield fixture.basemesh


def _applied_asset(basemesh, pack_name, kind="CURVES"):
    """The newest child of the basemesh loaded from the given pack asset."""
    found = [child for child in ObjectService.get_list_of_children(basemesh)
             if child.get(hairproperties.PACK_NAME_PROPERTY) == pack_name and child.type == kind]
    return found[-1] if found else None


def apply_hair(basemesh, pack_name=HAIR_ASSET, fur=False):
    """Apply a pack asset to the character, as the asset library would. Returns the hair object."""
    select(basemesh)
    if fur:
        bpy.ops.mpfb.apply_fur_operator(hair_asset=pack_name)
    else:
        bpy.ops.mpfb.apply_hair_operator(hair_asset=pack_name)
    hair_obj = _applied_asset(basemesh, pack_name)
    assert hair_obj is not None, f"Applying '{pack_name}' did not leave a hair object on the character"
    return hair_obj


def delete_hair(basemesh, asset_name, fur=False):
    select(basemesh)
    return bpy.ops.mpfb.delete_hair_operator(hair_asset=asset_name, is_fur=fur)


class AppliedAsset:
    """A character with one pack asset applied to it."""

    def __init__(self, basemesh, hair_obj, fur=False):
        self.basemesh = basemesh
        self.hair_obj = hair_obj
        self.asset_name = hair_obj.name
        self.fur = fur
        self.kind = "fur" if fur else "hair"
        self.properties = FUR_PROPERTIES if fur else HAIR_PROPERTIES

    @property
    def card_obj(self):
        return bpy.data.objects.get(f"{self.asset_name}{hairproperties.CARDS_OBJECT_SUFFIX}")

    def get(self, name, default=None):
        return self.properties.get_value(f"{self.asset_name}_{name}", default, entity_reference=self.basemesh)

    def set(self, name, value):
        # Same as a UI widget does it - through the property registered on the object type
        setattr(self.basemesh, f"{self.properties.dynamic_prefix}{self.asset_name}_{name}", value)

    def flag(self, flag):
        return hairproperties.get_cards_flag(self.properties, self.basemesh, self.asset_name, self.kind, flag)

    def run(self, operator_name, **properties):
        """Run one of the hair editor operators on this asset through bpy.ops."""
        select(self.basemesh)
        operator = getattr(bpy.ops.mpfb, operator_name)
        return operator(hair_asset=self.asset_name, is_fur=self.fur, **properties)


def _asset_fixture(pack_name, fur):
    require_pack_asset(pack_name, fur=fur)
    with HumanFixture() as fixture:
        asset = AppliedAsset(fixture.basemesh, apply_hair(fixture.basemesh, pack_name, fur=fur), fur=fur)
        try:
            yield asset
        finally:
            # The delete operator is what removes the asset's node groups and properties
            try:
                delete_hair(asset.basemesh, asset.asset_name, fur=fur)
            except Exception as e:
                print(f"Could not delete {asset.asset_name} after the test: {e}")


