def use_fast_bake(asset, destination, glossy=False):
    """The cheapest bake settings which still run the whole bake."""
    asset.set("cards_glossy", glossy)
    asset.set("cards_samples", 1)
    asset.set("cards_resolution", 64)
    asset.set("cards_texture_dst", str(destination))


# ---------------------------------------------------------------------------
# Calling operators directly
# ---------------------------------------------------------------------------

def operator_mock(operator_class, **properties):
    """A stand-in for the operator's self, carrying the operator's own helper methods and a recording report().

    Calling hardened_execute() on this instead of going through bpy.ops gives access to the WARNING and INFO
    reports, and an ERROR report does not turn into a RuntimeError.
    """
    methods = {}
    for klass in reversed(operator_class.__mro__):
        # Only MPFB's own classes. Blender's (bpy_types, or _bpy_types since 5.0) would bring their RNA __setattr__
        if "mpfb" not in klass.__module__:
            continue
        for name, value in vars(klass).items():
            if name in ("execute", "invoke", "poll", "__init__", "__doc__", "__module__"):
                continue
            if isinstance(value, (types.FunctionType, staticmethod)):
                methods[name] = value
    mock_class = type(f"Mock{operator_class.__name__}", (MockOperatorBase,), methods)
    return mock_class(**properties)


def run_hardened(operator_class, context_object, **properties):
    """Run an operator's hardened_execute() with a mock self. Returns (result, MockReport)."""
    select(context_object)
    mock = operator_mock(operator_class, **properties)
    result = operator_class.hardened_execute(mock, bpy.context)
    return result, mock.mock_report


# ---------------------------------------------------------------------------
# Small hand made scenes
# ---------------------------------------------------------------------------

def link(obj):
    bpy.context.collection.objects.link(obj)
    return obj


def make_hair_curves(name, strands, location=(0.0, 0.0, 0.0)):
    """A hair curves object with one curve per strand, each strand a list of (x, y, z) points."""
    curves = bpy.data.hair_curves.new(name)
    if strands:
        curves.add_curves([len(strand) for strand in strands])
        flat = [coordinate for strand in strands for point in strand for coordinate in point]
        curves.points.foreach_set("position", flat)
        curves.update_tag()
    obj = link(bpy.data.objects.new(name, curves))
    obj.location = location
    bpy.context.view_layer.update()
    return obj


def bundle_of_strands(root, count=5, length=0.2, spread=0.01, points=6, direction=(0.0, 0.0, 1.0)):
    """``count`` straight strands growing from around ``root`` in ``direction``."""
    strands = []
    for index in range(count):
        offset = (spread * (index - count / 2.0), spread * ((index * 7) % count - count / 2.0) * 0.5, 0.0)
        start = [root[axis] + offset[axis] for axis in range(3)]
        strands.append([tuple(start[axis] + direction[axis] * length * step / (points - 1) for axis in range(3))
                        for step in range(points)])
    return strands


def make_grid(name, faces_per_side=4, size=1.0, location=(0.0, 0.0, 0.0), with_uvs=True):
    """A flat square grid in the XY plane, with a UV layout covering 0..1 when ``with_uvs`` is set."""
    count = faces_per_side
    vertices = [(size * (column / count - 0.5), size * (row / count - 0.5), 0.0)
                for row in range(count + 1) for column in range(count + 1)]
    faces = [(row * (count + 1) + column, row * (count + 1) + column + 1,
              (row + 1) * (count + 1) + column + 1, (row + 1) * (count + 1) + column)
             for row in range(count) for column in range(count)]
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(vertices, [], faces)
    if with_uvs:
        uv_layer = mesh.uv_layers.new(name="UVMap")
        for loop in mesh.loops:
            vertex = vertices[loop.vertex_index]
            uv_layer.data[loop.index].uv = (vertex[0] / size + 0.5, vertex[1] / size + 0.5)
    mesh.update()
    obj = link(bpy.data.objects.new(name, mesh))
    obj.location = location
    bpy.context.view_layer.update()
    return obj


def make_separate_quads(name, count, width=0.02, height=0.08, gap=0.05, uv_per_card=True):
    """``count`` loose rectangular cards side by side, each with its own 0..1 UV layout (V along the card)."""
    vertices = []
    faces = []
    for index in range(count):
        x = index * (width + gap)
        base = len(vertices)
        vertices += [(x, 0.0, 0.0), (x + width, 0.0, 0.0), (x + width, 0.0, height), (x, 0.0, height)]
        faces.append((base, base + 1, base + 2, base + 3))
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(vertices, [], faces)
    uv_layer = mesh.uv_layers.new(name="UVMap")
    corner_uvs = ((0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0))
    for loop in mesh.loops:
        uv = corner_uvs[loop.vertex_index % 4]
        uv_layer.data[loop.index].uv = uv if uv_per_card else (uv[0] * 0.05, uv[1] * 0.05)
    mesh.update()
    return link(bpy.data.objects.new(name, mesh))


def make_material(name, color=(0.8, 0.2, 0.2, 1.0)):
    """A plain Principled material, standing in for a skin or a hair asset material."""
    material = bpy.data.materials.new(name)
    material.use_nodes = True
    principled = next(node for node in material.node_tree.nodes if node.bl_idname == 'ShaderNodeBsdfPrincipled')
    principled.inputs['Base Color'].default_value = color
    return material


def make_rig(name="TestRig"):
    armature = bpy.data.armatures.new(name)
    return link(bpy.data.objects.new(name, armature))


def surface_link_source(material):
    """The node feeding the Surface input of the material output, or None."""
    output = next((node for node in material.node_tree.nodes if node.bl_idname == 'ShaderNodeOutputMaterial'), None)
    if output is None or not output.inputs['Surface'].links:
        return None
    return output.inputs['Surface'].links[0].from_node


# ---------------------------------------------------------------------------
# Drawing the panel in background mode
# ---------------------------------------------------------------------------

class FakeOperatorProps:
    """What layout.operator() hands back, recording which bake setting a toggle was drawn for."""

    def __init__(self, log):
        object.__setattr__(self, "log", log)

    def __setattr__(self, name, value):
        if name == "setting":
            self.log.append(("bake_flag", value))
        object.__setattr__(self, name, value)


class FakeLayout:
    """Just enough of a blender UILayout to run the panel's draw code in background mode.

    Every call is recorded in ``log`` as (kind, name), so a test can ask what was drawn. Any UILayout
    method this fake has not been taught is swallowed, so that a new separator in the panel does not fail
    tests which are about something else.
    """

    def __init__(self, log):
        self.log = log

    def __getattr__(self, name):
        def swallow(*_args, **_kwargs):
            self.log.append((name, ""))
            return self
        return swallow

    def box(self):
        return self

    def row(self, **_kwargs):
        return self

    def column(self, **_kwargs):
        return self

    def label(self, text="", **_kwargs):
        self.log.append(("label", text))

    def prop(self, entity, property_name, **_kwargs):
        # This is what would raise if the property did not exist on the entity
        getattr(entity, property_name) if not property_name.startswith('["') else entity[property_name[2:-2]]
        self.log.append(("prop", property_name))

    def operator(self, idname, **_kwargs):
        self.log.append(("operator", idname))
        return FakeOperatorProps(self.log)

    def template_color_ramp(self, entity, property_name, **_kwargs):
        getattr(entity, property_name)
        self.log.append(("template_color_ramp", property_name))


def panel_instance(layout=None):
    """The panel's methods, bound to a plain object so they can be called outside blender's UI."""
    panel = types.SimpleNamespace(layout=layout)
    for klass in reversed(haireditorpanel.MPFB_PT_Hair_Editor_Panel.__mro__):
        if klass.__module__.startswith("bpy"):
            continue
        for name, attribute in vars(klass).items():
            if isinstance(attribute, types.FunctionType):
                setattr(panel, name, attribute.__get__(panel))
    return panel


def labels(log):
    return [name for kind, name in log if kind == "label"]


def drawn_props(log):
    return [name for kind, name in log if kind == "prop"]


def drawn_flags(log):
    return [name for kind, name in log if kind == "bake_flag"]


def unfold_every_section(asset_name):
    """Open every foldable section, so that a draw check can see the controls inside them."""
    for section in ("colour", "strands", "frizz", "roll", "clump", "noise", "curl", "groom_other",
                    "placement", "shape", "appearance", "texture", "capture", "maps", "lights"):
        toggle_section_operator._OPEN_SECTIONS[(asset_name, section)] = True


def draw_asset_block(asset):
    """Draw the asset's whole block of the panel, with every section unfolded. Returns the log."""
    asset.set(f"{asset.kind}_asset_open", True)
    unfold_every_section(asset.asset_name)
    log = []
    panel_instance()._asset_block(asset.basemesh, FakeLayout(log), asset.asset_name, asset.fur)
    return log


def tmp_texture_dir(tmp_path):
    destination = os.path.join(str(tmp_path), "baked")
    os.makedirs(destination, exist_ok=True)
    return destination
